    // spread *centre*, not the page corner, so this is (-pageW/2, -pageH/2) \u2014 NOT
    // (0,0). Placing content at spread (0,0) would land it at the page centre and
    // push most of it off the bottom-right; everything below anchors to pageTL.
    const pageTL = pageSpaceBounds(tmp.pages.item(0));

